# -*- coding: utf-8 -*-
from pymongosql.sql.parser import SQLParser
from pymongosql.sql.update_builder import UpdateExecutionPlan


class TestSQLParserUpdate:
    """Tests for UPDATE parsing via AST visitor (PartiQL-style)."""

    def test_update_simple_field(self):
        """Test UPDATE with single field update."""
        sql = "UPDATE users SET name = 'John'"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "users"
        assert plan.update_fields == {"name": "John"}
        assert plan.filter_conditions == {}

    def test_update_multiple_fields(self):
        """Test UPDATE with multiple field updates."""
        sql = "UPDATE products SET price = 100, stock = 50"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "products"
        assert plan.update_fields == {"price": 100, "stock": 50}
        assert plan.filter_conditions == {}

    def test_update_with_where_clause(self):
        """Test UPDATE with WHERE clause."""
        sql = "UPDATE orders SET status = 'shipped' WHERE id = 123"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "orders"
        assert plan.update_fields == {"status": "shipped"}
        assert plan.filter_conditions == {"id": 123}

    def test_update_numeric_value(self):
        """Test UPDATE with numeric value."""
        sql = "UPDATE inventory SET quantity = 100 WHERE product_id = 5"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "inventory"
        assert plan.update_fields == {"quantity": 100}
        assert plan.filter_conditions == {"product_id": 5}

    def test_update_boolean_value(self):
        """Test UPDATE with boolean value."""
        sql = "UPDATE settings SET enabled = true WHERE setting_key = 'feature_flag'"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "settings"
        assert plan.update_fields == {"enabled": True}
        assert plan.filter_conditions == {"setting_key": "feature_flag"}

    def test_update_null_value(self):
        """Test UPDATE with NULL value."""
        sql = "UPDATE cache SET expires = null WHERE session_id = 'abc123'"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "cache"
        assert plan.update_fields == {"expires": None}
        assert plan.filter_conditions == {"session_id": "abc123"}

    def test_update_with_comparison_operators(self):
        """Test UPDATE with various comparison operators in WHERE."""
        sql = "UPDATE products SET discount = 0.1 WHERE price > 100"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "products"
        assert plan.update_fields == {"discount": 0.1}
        assert plan.filter_conditions == {"price": {"$gt": 100}}

    def test_update_with_and_condition(self):
        """Test UPDATE with AND condition in WHERE."""
        sql = "UPDATE items SET status = 'archived' WHERE category = 'old' AND year < 2020"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "items"
        assert plan.update_fields == {"status": "archived"}
        assert "$and" in plan.filter_conditions
        assert len(plan.filter_conditions["$and"]) == 2

    def test_update_validates_execution_plan(self):
        """Test that validation is called on the execution plan."""
        sql = "UPDATE users SET email = 'test@example.com' WHERE id = 1"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.validate() is True
        assert plan.collection == "users"

    def test_update_nested_field(self):
        """Test UPDATE with nested field path."""
        sql = "UPDATE users SET address.city = 'NYC' WHERE id = 1"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "users"
        assert "address.city" in plan.update_fields
        assert plan.update_fields["address.city"] == "NYC"

    def test_update_with_parameter_placeholder(self):
        """Test UPDATE with parameter placeholder."""
        sql = "UPDATE users SET name = '?' WHERE id = '?'"
        plan = SQLParser(sql).get_execution_plan()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "users"
        assert plan.update_fields == {"name": "?"}
        assert plan.filter_conditions == {"id": "?"}

# -*- coding: utf-8 -*-
import pytest

from pymongosql.executor import StandardQueryExecution


class TestPositionalParameters:
    """Test suite for positional parameters with ? placeholders"""

    def test_simple_positional_replacement(self):
        """Test basic positional parameter replacement in filter"""
        execution = StandardQueryExecution()

        test_filter = {"age": "?", "status": "?"}
        params = [25, "active"]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"age": 25, "status": "active"}

    def test_nested_positional_replacement(self):
        """Test positional parameter replacement in nested filter"""
        execution = StandardQueryExecution()

        test_filter = {"profile": {"age": "?"}, "status": "?"}
        params = [30, "inactive"]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"profile": {"age": 30}, "status": "inactive"}

    def test_list_positional_replacement(self):
        """Test positional parameter replacement in list"""
        execution = StandardQueryExecution()

        test_filter = {"items": ["?", "?"], "name": "?"}
        params = [1, 2, "test"]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"items": [1, 2], "name": "test"}

    def test_mixed_positional_replacement(self):
        """Test positional parameter replacement with mixed data types"""
        execution = StandardQueryExecution()

        test_filter = {"$gt": "?", "$lt": "?", "status": "?"}
        params = [18, 65, "active"]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"$gt": 18, "$lt": 65, "status": "active"}

    def test_insufficient_positional_parameters(self):
        """Test error when not enough positional parameters provided"""
        from pymongosql.error import ProgrammingError

        execution = StandardQueryExecution()

        test_filter = {"age": "?", "status": "?"}
        params = [25]  # Only one parameter provided

        with pytest.raises(ProgrammingError) as exc_info:
            execution._replace_placeholders(test_filter, params)

        assert "Not enough parameters" in str(exc_info.value)

    def test_complex_nested_positional_replacement(self):
        """Test positional parameters in complex nested structures"""
        execution = StandardQueryExecution()

        test_filter = {"$and": [{"age": {"$gt": "?"}}, {"profile": {"status": "?"}}, {"items": ["?", "?"]}]}
        params = [25, "active", 1, 2]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"$and": [{"age": {"$gt": 25}}, {"profile": {"status": "active"}}, {"items": [1, 2]}]}


class TestParameterTypes:
    """Test parameter handling with different data types"""

    def test_positional_with_numeric_types(self):
        """Test positional parameters with int and float"""
        execution = StandardQueryExecution()

        test_filter = {"age": "?", "salary": "?"}
        params = [25, 50000.50]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"age": 25, "salary": 50000.50}

    def test_positional_with_boolean(self):
        """Test positional parameters with boolean values"""
        execution = StandardQueryExecution()

        test_filter = {"active": "?", "verified": "?"}
        params = [True, False]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"active": True, "verified": False}

    def test_positional_with_null(self):
        """Test positional parameters with None value"""
        execution = StandardQueryExecution()

        test_filter = {"deleted_at": "?"}
        params = [None]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"deleted_at": None}

    def test_positional_with_list_value(self):
        """Test positional parameter with list as value"""
        execution = StandardQueryExecution()

        test_filter = {"tags": "?"}
        params = [["python", "mongodb"]]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"tags": ["python", "mongodb"]}

    def test_positional_with_dict_value(self):
        """Test positional parameter with dict as value"""
        execution = StandardQueryExecution()

        test_filter = {"metadata": "?"}
        params = [{"key": "value"}]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"metadata": {"key": "value"}}


class TestEdgeCases:
    """Test edge cases and special scenarios"""

    def test_empty_filter_with_parameters(self):
        """Test parameters with empty filter"""
        execution = StandardQueryExecution()

        result = execution._replace_placeholders({}, [])
        assert result == {}

    def test_non_placeholder_strings_untouched(self):
        """Test that non-placeholder strings are not modified"""
        execution = StandardQueryExecution()

        test_filter = {"status": "active", "query": "search"}
        params = [25, "test"]
        result = execution._replace_placeholders(test_filter, params)

        assert result == {"status": "active", "query": "search"}

# -*- coding: utf-8 -*-
import os

import pytest

from pymongosql.connection import Connection

# Centralized test configuration sourced from environment to allow running tests
# against remote MongoDB (e.g. Atlas) or local test instance.
TEST_URI = os.environ.get("PYMONGOSQL_TEST_URI") or os.environ.get("MONGODB_URI")
TEST_DB = os.environ.get("PYMONGOSQL_TEST_DB", "test_db")


def make_conn(**kwargs):
    """Create a Connection using TEST_URI if provided, otherwise use a local default."""
    if TEST_URI:
        if "database" not in kwargs:
            kwargs["database"] = TEST_DB
        return Connection(host=TEST_URI, **kwargs)

    # Default local connection parameters
    defaults = {"host": "mongodb://testuser:testpass@localhost:27017/test_db?authSource=test_db", "database": "test_db"}
    for k, v in defaults.items():
        kwargs.setdefault(k, v)
    return Connection(**kwargs)


def make_superset_conn(**kwargs):
    """Create a superset-mode Connection using TEST_URI if provided, otherwise use a local default."""
    if TEST_URI:
        # Convert test URI to superset mode by adding ?mode=superset query parameter
        if "?" in TEST_URI:
            superset_uri = TEST_URI + "&mode=superset"
        else:
            superset_uri = TEST_URI + "?mode=superset"
        if "database" not in kwargs:
            kwargs["database"] = TEST_DB
        return Connection(host=superset_uri, **kwargs)

    # Default local connection parameters with superset mode
    defaults = {
        "host": "mongodb://testuser:testpass@localhost:27017/test_db?authSource=test_db&mode=superset",
        "database": "test_db",
    }
    for k, v in defaults.items():
        kwargs.setdefault(k, v)
    return Connection(**kwargs)


@pytest.fixture
def conn():
    """Yield a Connection instance configured via environment variables and tear it down after use."""
    connection = make_conn()
    try:
        yield connection
    finally:
        try:
            connection.close()
        except Exception:
            pass


@pytest.fixture
def superset_conn():
    """Yield a superset-mode Connection instance and tear it down after use."""
    connection = make_superset_conn()
    try:
        yield connection
    finally:
        try:
            connection.close()
        except Exception:
            pass


@pytest.fixture
def make_connection():
    """Provide the helper make_conn function to tests that need to create connections with custom args."""
    return make_conn


# SQLAlchemy version compatibility
try:
    import sqlalchemy
    from sqlalchemy import create_engine
    from sqlalchemy.orm import sessionmaker

    SQLALCHEMY_VERSION = tuple(map(int, sqlalchemy.__version__.split(".")[:2]))
    SQLALCHEMY_2X = SQLALCHEMY_VERSION >= (2, 0)
    HAS_SQLALCHEMY = True

    # Handle declarative base differences
    if SQLALCHEMY_2X:
        try:
            from sqlalchemy.orm import DeclarativeBase, Session

            class Base(DeclarativeBase):
                pass

        except ImportError:
            from sqlalchemy.ext.declarative import declarative_base

            Base = declarative_base()
            from sqlalchemy.orm import Session
    else:
        from sqlalchemy.ext.declarative import declarative_base
        from sqlalchemy.orm import Session

        Base = declarative_base()

except ImportError:
    SQLALCHEMY_VERSION = None
    SQLALCHEMY_2X = False
    HAS_SQLALCHEMY = False
    Base = None
    Session = None

# SQLAlchemy fixtures for dialect testing
if HAS_SQLALCHEMY:

    @pytest.fixture
    def sqlalchemy_engine():
        """Provide a SQLAlchemy engine connected to MongoDB. The URI is taken from environment variables
        (PYMONGOSQL_TEST_URI or MONGODB_URI) or falls back to a sensible local default.
        """
        uri = os.environ.get("PYMONGOSQL_TEST_URI") or os.environ.get("MONGODB_URI") or TEST_URI
        db = os.environ.get("PYMONGOSQL_TEST_DB") or TEST_DB

        def _ensure_uri_has_db(uri_value: str, database: str) -> str:
            if not database:
                return uri_value
            idx = uri_value.find("://")
            if idx == -1:
                return uri_value
            rest = uri_value[idx + 3 :]
            if "/" in rest:
                after = rest.split("/", 1)[1]
                if after == "" or after.startswith("?"):
                    return uri_value.rstrip("/") + "/" + database
                return uri_value
            return uri_value.rstrip("/") + "/" + database

        if uri:
            uri_to_use = _ensure_uri_has_db(uri, db)
        else:
            uri_to_use = "mongodb://testuser:testpass@localhost:27017/test_db"

        engine = create_engine(uri_to_use)
        yield engine
        engine.dispose()

    @pytest.fixture
    def session_maker(sqlalchemy_engine):
        """Provide a SQLAlchemy session maker."""
        return sessionmaker(bind=sqlalchemy_engine)

# -*- coding: utf-8 -*-
import pytest

from pymongosql.sql.update_builder import MongoUpdateBuilder, UpdateExecutionPlan


class TestUpdateExecutionPlan:
    """Test UpdateExecutionPlan dataclass."""

    def test_to_dict(self):
        """Test to_dict conversion."""
        plan = UpdateExecutionPlan(
            collection="users", update_fields={"name": "John", "age": 30}, filter_conditions={"id": 123}
        )

        result = plan.to_dict()
        assert result["collection"] == "users"
        assert result["filter"] == {"id": 123}
        assert result["update"] == {"$set": {"name": "John", "age": 30}}

    def test_validate_success(self):
        """Test validate returns True for valid plan."""
        plan = UpdateExecutionPlan(collection="products", update_fields={"price": 99.99})

        assert plan.validate() is True

    def test_validate_no_update_fields(self):
        """Test validate fails when no update fields."""
        plan = UpdateExecutionPlan(collection="products", update_fields={})

        assert plan.validate() is False

    def test_validate_empty_filter_allowed(self):
        """Test validate allows empty filter (update all)."""
        plan = UpdateExecutionPlan(collection="products", update_fields={"status": "active"}, filter_conditions={})

        assert plan.validate() is True

    def test_copy(self):
        """Test copy creates independent copy."""
        original = UpdateExecutionPlan(
            collection="orders", update_fields={"status": "shipped", "total": 100}, filter_conditions={"id": 456}
        )

        copy = original.copy()

        # Verify all fields copied
        assert copy.collection == original.collection
        assert copy.update_fields == original.update_fields
        assert copy.filter_conditions == original.filter_conditions

        # Verify it's independent
        copy.collection = "new_collection"
        copy.update_fields["new_field"] = "value"
        assert original.collection == "orders"
        assert "new_field" not in original.update_fields

    def test_copy_with_empty_fields(self):
        """Test copy handles empty dicts."""
        original = UpdateExecutionPlan(collection="test", update_fields={"field": "value"})

        copy = original.copy()
        assert copy.filter_conditions == {}

    def test_get_mongo_update_doc(self):
        """Test get_mongo_update_doc returns $set document."""
        plan = UpdateExecutionPlan(collection="users", update_fields={"email": "user@example.com", "verified": True})

        update_doc = plan.get_mongo_update_doc()
        assert update_doc == {"$set": {"email": "user@example.com", "verified": True}}

    def test_parameter_style_default(self):
        """Test default parameter style is qmark."""
        plan = UpdateExecutionPlan(collection="test", update_fields={"a": "b"})
        assert plan.parameter_style == "qmark"


class TestMongoUpdateBuilder:
    """Test MongoUpdateBuilder class."""

    def test_collection(self):
        """Test setting collection name."""
        builder = MongoUpdateBuilder()
        result = builder.collection("users")

        assert builder._plan.collection == "users"
        assert result is builder  # Fluent interface

    def test_update_fields(self):
        """Test setting update fields."""
        builder = MongoUpdateBuilder()
        builder.update_fields({"name": "Alice", "age": 25})

        assert builder._plan.update_fields == {"name": "Alice", "age": 25}

    def test_update_fields_empty_dict(self):
        """Test update_fields with empty dict doesn't update."""
        builder = MongoUpdateBuilder()
        builder.update_fields({})

        assert builder._plan.update_fields == {}

    def test_update_fields_none(self):
        """Test update_fields with None doesn't update."""
        builder = MongoUpdateBuilder()
        builder._plan.update_fields = {"existing": "field"}
        builder.update_fields(None)

        # Should preserve existing
        assert builder._plan.update_fields == {"existing": "field"}

    def test_filter_conditions(self):
        """Test setting filter conditions."""
        builder = MongoUpdateBuilder()
        builder.filter_conditions({"status": "active", "age": {"$gt": 18}})

        assert builder._plan.filter_conditions == {"status": "active", "age": {"$gt": 18}}

    def test_filter_conditions_empty(self):
        """Test filter_conditions with empty dict doesn't update."""
        builder = MongoUpdateBuilder()
        builder.filter_conditions({})

        assert builder._plan.filter_conditions == {}

    def test_filter_conditions_none(self):
        """Test filter_conditions with None doesn't update."""
        builder = MongoUpdateBuilder()
        builder._plan.filter_conditions = {"existing": "filter"}
        builder.filter_conditions(None)

        # Should preserve existing
        assert builder._plan.filter_conditions == {"existing": "filter"}

    def test_parameter_style(self):
        """Test setting parameter style."""
        builder = MongoUpdateBuilder()
        builder.parameter_style("named")

        assert builder._plan.parameter_style == "named"

    def test_build_success(self):
        """Test build returns execution plan when valid."""
        builder = MongoUpdateBuilder()
        builder.collection("products").update_fields({"price": 49.99})

        plan = builder.build()

        assert isinstance(plan, UpdateExecutionPlan)
        assert plan.collection == "products"
        assert plan.update_fields == {"price": 49.99}

    def test_build_validation_failure(self):
        """Test build raises ValueError when validation fails."""
        builder = MongoUpdateBuilder()
        builder.collection("products")
        # Don't set update_fields

        with pytest.raises(ValueError) as exc_info:
            builder.build()

        assert "invalid update plan" in str(exc_info.value).lower()

    def test_fluent_interface_chaining(self):
        """Test all methods return self for chaining."""
        builder = MongoUpdateBuilder()

        result = (
            builder.collection("orders")
            .update_fields({"status": "shipped"})
            .filter_conditions({"id": 123})
            .parameter_style("qmark")
        )

        assert result is builder
        assert builder._plan.collection == "orders"
        assert builder._plan.update_fields == {"status": "shipped"}
        assert builder._plan.filter_conditions == {"id": 123}
        assert builder._plan.parameter_style == "qmark"

# -*- coding: utf-8 -*-
from pymongosql.sql.query_handler import FromHandler, QueryParseResult, SelectHandler, WhereHandler


class TestQueryParseResult:
    """Test QueryParseResult dataclass."""

    def test_for_visitor_factory(self):
        """Test factory method creates fresh instance."""
        result = QueryParseResult.for_visitor()
        assert result.filter_conditions == {}
        assert result.has_errors is False
        assert result.error_message is None
        assert result.collection is None
        assert result.projection == {}
        assert result.column_aliases == {}
        assert result.sort_fields == []
